/* From Uiverse.io by AmIt-DasIT - Tags: button */
.__UIV_SCOPE__ .box {
  width: 45px;
  height: 45px;
  background: #5cda5c;
  border-radius: 25px;
  display: flex;
  justify-items: center;
  justify-content: center;
  align-items: center;
  transition: 0.3s;
  cursor: pointer;
  position: relative;
}

.__UIV_SCOPE__ .arrow {
  border: solid black;
  border-width: 0 3px 3px 0;
  display: inline-block;
  padding: 3px;
}

.__UIV_SCOPE__ .right {
  transform: rotate(-45deg);
}

.__UIV_SCOPE__ .box:hover {
  width: 160px;
  background: linear-gradient(to right, #26d526, yellow);
}

.__UIV_SCOPE__ .box:hover .arrow {
  display: none;
}

.__UIV_SCOPE__ .box .text {
  display: none;
}

.__UIV_SCOPE__ .box:hover .text {
  display: flex;
  font-size: 16px;
  font-weight: 550;
  color: black;
  letter-spacing: 0.6px;
  animation: anima 0.6s ease;
}

@keyframes anima {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

.__UIV_SCOPE__ .box:active {
  background: linear-gradient(to right, rgb(38, 213, 38, 0.8), rgba(255, 255, 0, 0.8));
}
